function UserAvatar({ userId }: { userId: string }) {
  const { data } = useQuery({
    queryKey: ['user', userId],
    queryFn: () => fetch(`/api/users/${userId}`).then(res => res.json()),
    select: (user) => ({
      name: user.name,
      avatar: user.avatar
    })
  });

  return (
    <img
      src={data.avatar}
      alt={data.name}
      className="h-10 w-10 rounded-full"
    />
  );
}

function UserCard({ userId, showEmail }: { userId: string; showEmail: boolean }) {
  const selectUser = useMemo(() => (user: User) => ({
    name: user.name,
    avatar: user.avatar,
    ...(showEmail && { email: user.email })
  }), [showEmail]);

  const { data } = useQuery({
    queryKey: ['user', userId],
    queryFn: fetchUser,
    select: selectUser
  });

  return (
    <div>
      <h2>{data.name}</h2>
      <img src={data.avatar} alt={data.name} />
      {showEmail && <p>{data.email}</p>}
    </div>
  );
}

// General Programming Example
class Example {
  constructor(config) {
    this.config = {
      enabled: true,
      debug: false,
      maxRetries: 3,
      timeout: 5000,
      ...config
    };
  }

  async process(input) {
    // Step 1: Validate input
    this.validate(input);

    // Step 2: Process with retry logic
    let attempts = 0;
    while (attempts < this.config.maxRetries) {
      try {
        const result = await this.execute(input);
        return { success: true, data: result };
      } catch (error) {
        attempts++;
        if (attempts >= this.config.maxRetries) {
          return { success: false, error: error.message };
        }
      }
    }
  }

  validate(input) {
    if (!input) {
      throw new Error('Input cannot be null or undefined');
    }
  }

  async execute(input) {
    // Implementation here
    return { processed: true, timestamp: Date.now() };
  }
}

// Usage
const example = new Example({ debug: true });
example.process({ id: 1 }).then(console.log);

